        "StringEquals": {
          "kms:ViaService": [
            "s3.us-east-1.amazonaws.com",
            "lambda.us-east-1.amazonaws.com"
          ],
          "aws:SourceAccount": "123456789012"
        }
      }
    },
    {
      "Sid": "AllowS3ToUseKey",
      "Effect": "Allow",
      "Principal": {
        "Service": "s3.amazonaws.com"
      },
      "Action": [
        "kms:GenerateDataKey",
        "kms:Decrypt"
      ],
      "Resource": "*",
      "Condition": {
        "StringEquals": {
          "aws:SourceAccount": "123456789012"
        },
        "StringLike": {
          "kms:ViaService": "s3.us-east-1.amazonaws.com"
        }
      }
