## 4. Script Snippet to Verify S3 Object Encryption Metadata (Node.js example)

```javascript
import { S3Client, ListObjectsV2Command, HeadObjectCommand } from "@aws-sdk/client-s3";

const s3Client = new S3Client({ region: "us-east-1" });

// Replace with your bucket name and KMS Key ID ARN
const bucketName = "your-processed-bucket-name";
const expectedKmsKeyId = "arn:aws:kms:us-east-1:123456789012:key/your-kms-key-id";

async function verifyEncryption() {
  let continuationToken;
  do {
    const listParams = { Bucket: bucketName, ContinuationToken: continuationToken };
    const listResponse = await s3Client.send(new ListObjectsV2Command(listParams));

    for (const obj of listResponse.Contents || []) {
      const headParams = { Bucket: bucketName, Key: obj.Key };
      const headResponse = await s3Client.send(new HeadObjectCommand(headParams));

      const sse = headResponse.ServerSideEncryption;
      const kmsKeyId = headResponse.SSEKMSKeyId;

      if (sse !== "aws:kms" || kmsKeyId !== expectedKmsKeyId) {
        console.warn(`Object ${obj.Key} is NOT encrypted with the expected KMS key.`);
      } else {
        console.log(`Object ${obj.Key} is properly encrypted.`);
      }
    }

    continuationToken = listResponse.IsTruncated ? listResponse.NextContinuationToken : undefined;
  } while (continuationToken);
}

verifyEncryption().catch((err) => {
  console.error("Error verifying encryption:", err);
});
```

